tasks.solution:
fn main() {
    let title = String::from("러스트 입문");
    // 원본 제목도 계속 써야 해요. 이 줄을 고쳐 별도 복사본을 넣으세요.
    // clone은 같은 내용의 String을 새로 만들어요. title의 소유권은 그대로예요.
    let mut copy = title.clone();
    // 사본에만 글자를 붙여요. 원본은 바뀌지 않아요.
    copy.push_str(" (사본)");
    // 원본과 사본을 차례로 출력해 서로 다른 값인지 봐요.
    println!("{title}");
    println!("{copy}");
}

