tasks.solution:
fn add_edition(title: String) -> String {
    // 넘겨받은 제목에 판 정보를 붙여 돌려줘요.
    // 매개변수 title이 소유권을 받았으니 함수 안에서 마음대로 옮기고 바꿀 수 있어요.
    let mut result = title;
    result.push_str(" 2판");
    // 끝 식 result를 돌려주면 소유권이 호출한 쪽으로 다시 옮겨 가요.
    result
}

fn main() {
    let title = String::from("러스트 입문");
    // 이 두 줄을 고쳐 돌려받은 제목을 edited에 담아 출력하세요.
    // title은 이 호출에서 함수로 옮겨 가요. 돌려받은 값은 edited가 소유해요.
    let edited = add_edition(title);
    // 옮겨 간 title이 아니라 지금 소유자 edited를 출력해요.
    println!("{edited}");
}

