tasks.solution:
fn is_low(stock: &i32) -> bool {
    // stock은 정수를 빌린 참조예요.
    // 이 줄을 고쳐 참조가 가리키는 정수를 3과 비교하세요.
    // *stock은 참조가 가리키는 정수예요. 그 정수를 3과 비교해요.
    *stock < 3
}

fn main() {
    // main의 stock은 참조가 아니라 정수 그대로예요.
    let stock = 2;
    // &stock으로 빌려주고 비교 결과 bool을 돌려받아요.
    let low = is_low(&stock);
    println!("부족: {low}");
}

