tasks.solution:
fn add_edition(title: &mut String) {
    // 빌린 제목 끝에 판 정보를 붙여요.
    // 매개변수 타입을 고쳐 바꿀 수 있게 빌려 받으세요.
    // &mut String은 바꿀 수 있는 빌림이에요. 소유권은 여전히 main의 title에 있어요.
    title.push_str(" 2판");
}

fn main() {
    // 바꿀 수 있게 빌려주려면 원래 이름도 let mut여야 해요.
    let mut title = String::from("러스트 입문");
    // 이 줄을 고쳐 바꿀 수 있게 빌려주세요.
    // &mut title로 빌려주면 함수가 붙인 글자가 원래 title에 남아요.
    add_edition(&mut title);
    println!("{title}");
}

