tasks.solution:
fn main() {
    let mut title = String::from("러스트 입문");
    // first의 빌림은 first를 마지막으로 쓰는 다음 줄에서 끝나요.
    let first = &mut title;
    // 아래 first.push_str 줄을 이 second 줄 위로 옮기세요.
