    sell(&stock);
    show(&title, &stock);
}

tasks.solution:
fn sell(stock: &mut i32) {
    // 판매 한 건마다 재고를 1 줄여요.
    // 매개변수와 이 줄을 고쳐 원래 재고를 바꾸세요.
    // stock은 참조라서 *stock이 가리키는 재고 정수예요. 그 정수에서 1을 빼요.
    *stock -= 1;
}

fn show(title: &String, stock: &i32) {
    // 읽기만 하는 함수라 & 빌림으로 충분해요.
    println!("{title} 재고: {stock}");
}

fn main() {
    let title = String::from("러스트 입문");
    // sell이 바꿀 재고라 let mut로 선언돼 있어요.
    let mut stock = 3;
    // 이 줄을 고쳐 sell이 바꿀 수 있게 빌려주세요.
    // &mut로 빌려준 동안 sell이 바꾼 값이 원래 stock에 남아요.
    sell(&mut stock);
    // 변경 빌림은 sell 호출에서 끝났으니 다시 &로 읽을 수 있어요.
    show(&title, &stock);
}
